import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

public class AK375 {
    public static Scanner scanner = new Scanner(System.in);
    public String ak375(int n, String str) {
        StringBuilder buffer1 = new StringBuilder();
        StringBuilder buffer2 = new StringBuilder();
        int maxLength = 0;
        int nestedCount = 0;

        for (int i = 0; i < n; i++) {
            char c = str.charAt(i);
            if (c == '(') {
                buffer2.append('_');
                int j = i + 1;
                while (j < n && str.charAt(j) != ')') {
                    buffer2.append(str.charAt(j));
                    j++;
                }
                i = j; // skip to position after ')'
            } else if (c == ')') {
                buffer1.append('_');
            } else {
                buffer1.append(c);
            }
        }

        String[] parts2 = buffer2.toString().split("_");
        List<String> list2 = new ArrayList<>();
        for (String part : parts2) {
            if (part != null && !part.isEmpty()) {
                list2.add(part);
            }
        }
        int count2 = list2.size();

        String[] parts1 = buffer1.toString().split("_");
        for (String part : parts1) {
            if (part.length() > maxLength) {
                maxLength = part.length();
            }
        }
        return maxLength + " " + count2;
    }

    public static void main(String[] args) {
        while (scanner.hasNext()) {
            int n = scanner.nextInt();
            String str = scanner.next();
            long startTime = System.currentTimeMillis();
            String result = new AK375().ak375(n, str);
            long endTime = System.currentTimeMillis();
            System.out.println(result);
        }
    }
}
